/**
 * Main tab bar SSOT — labels + native asset names (xcasset / drawable).
 * Assets are generated by `plugins/with-native-tab-icons.js` at prebuild.
 */

export type MainTabName = 'home' | 'challenge' | 'mypage';

export type TabIconAssetPair = {
  /** Unselected (line) asset name — xcasset & drawable */
  default: string;
  /** Selected (solid) asset name — xcasset & drawable */
  selected: string;
};

export type MainTabSpec = {
  name: MainTabName;
  label: string;
  icons: TabIconAssetPair;
  /** Show unread notice badge on this tab when true at runtime */
  noticeBadge?: boolean;
};

/** Visible production tabs, in bar order. */
export const MAIN_TAB_SPECS: readonly MainTabSpec[] = [
  {
    name: 'home',
    label: '홈',
    icons: { default: 'tab_home_line', selected: 'tab_home_solid' },
  },
  {
    name: 'challenge',
    label: '챌린지∙통계',
    icons: { default: 'tab_challenge_line', selected: 'tab_challenge_solid' },
  },
  {
    name: 'mypage',
    label: '설정',
    icons: { default: 'tab_setting_line', selected: 'tab_setting_solid' },
    noticeBadge: true,
  },
] as const;

/** SVG sources for the config plugin (paths relative to project root). */
export const MAIN_TAB_ICON_SVG_SOURCES: readonly {
  assetName: string;
  svgPath: string;
}[] = [
  { assetName: 'tab_home_line', svgPath: 'assets/images/icons/line/home.svg' },
  { assetName: 'tab_home_solid', svgPath: 'assets/images/icons/solid/home.svg' },
  { assetName: 'tab_challenge_line', svgPath: 'assets/images/icons/line/challenge.svg' },
  { assetName: 'tab_challenge_solid', svgPath: 'assets/images/icons/solid/challenge.svg' },
  { assetName: 'tab_setting_line', svgPath: 'assets/images/icons/line/setting.svg' },
  { assetName: 'tab_setting_solid', svgPath: 'assets/images/icons/solid/setting.svg' },
] as const;
